mapper.select:
select clue.*,user.name as assignName from clue
left join user on clue.user_Id = user.id


        clue.id = #{clueDto.clueId}


        and clue.phone like CONCAT('%', #{clueDto.phone}, '%')


        and clue.status = #{clueDto.status}


        and clue.channel = #{clueDto.channel}



        and user.name like CONCAT('%', #{clueDto.assignName}, '%')



order by clue.id desc

select clue.*,activity.name as activityName from clue left join activity on clue.activity_id = activity.id
and clue.user_id is null
and clue.status = #{clue.status}
and clue.phone like concat('%', #{clue.phone}, '%')
and clue.channel = #{clue.channel}
order by clue.id desc
